SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#c6eff3");
  SZGame2D.enableClassicControls("auto");
  let emVoo = false;
  let bolhaVisivel = false;
  let fim = false;
  let lancamentos = 0;
  let pontos = 0;
  let tempo = 8;
  let recorde = 0;
  const mira = SZGame2D.createSprite({ x: 72, y: 360, w: 48, h: 48, image: "mira" });
  const bolha = SZGame2D.createSprite({ x: 64, y: 340, w: 64, h: 64, image: "bolha" });
  const alvo = SZGame2D.createSprite({ x: 60, y: 120, w: 56, h: 56, image: "alvo" });
  // Quando acontecer
  SZGame2D.onKey("Space", () => {

  }, "recife_quadro_1_events_0");
  SZGame2D.onKey("Enter", () => {

  }, "recife_quadro_1_events_1");
  SZGame2D.onOverlap(() => bolha, () => alvo, () => {

  }, "recife_quadro_1_events_2");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.arrowsX(mira, 3);
    SZGame2D.clampToScreen(mira, ctx);
    if (emVoo) {
      SZGame2D.applyVelocity(bolha);
      if (SZGame2D.spriteY(bolha) < -64) {
        emVoo = false;
        bolhaVisivel = false;
        bolha.vx = 0; bolha.vy = 0;
      }
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "recife");
    SZGame2D.drawLabel(ctx, "Uma bolha por vez", 18, 32, "#123d55", 24, "left");
    SZGame2D.drawLabel(ctx, "Setas mexem a mira. Espaço ou A solta a bolha.", 18, 60, "#123d55", 16, "left");
    SZGame2D.drawSprite(ctx, alvo);
    SZGame2D.drawSprite(ctx, mira);
    if (bolhaVisivel) {
      SZGame2D.drawSprite(ctx, bolha);
    }
    SZGame2D.drawScore(ctx, "Pontos: ", pontos, 490, 32, "#123d55", 18);
  }, "recife_quadro_1_loops_0");
}, "__sz-project");

